<?php require __DIR__.'/bootstrap.php';if(current_user())redirect('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';if(!$name||!$email||!$phone||strlen($password)<10){$error='Use a valid email and a password of at least 10 characters.';}else{try{db()->prepare('INSERT INTO users(name,email,password_hash,phone) VALUES(?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone]);flash('Registration complete. Please log in.');redirect('login.php');}catch(PDOException $e){$error='That email is already registered.';}}}page_top('Register');?><form class="form-card" method="post"><h1>Dealer registration</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Name</label><input name="name" required><label>Email</label><input name="email" type="email" required><label>Phone</label><input name="phone" required><label>Password</label><input name="password" type="password" minlength="10" required><button class="button">Create account</button></form><?php page_bottom();
